"""Notification log helpers. Notifications live in state["notes"] as tuples."""


def emit(s, *note):
    s["notes"].append(tuple(note))


def sync_overdraw(s):
    """Emit OVERDRAWN when cash crosses below 0; re-arm once cash is >= 0."""
    if s["cash"] < 0:
        if not s["overdrawn"]:
            s["overdrawn"] = True
            emit(s, "OVERDRAWN")
    else:
        s["overdrawn"] = False


def update_reorder_flag(s, sku, wh, stock, announce):
    """Track the REORDER latch for (sku, wh). Emit only when `announce` is True."""
    level = s["items"][sku]["reorder_level"]
    key = (sku, wh)
    if stock > level:
        s["reorder_sent"].discard(key)
    elif announce and key not in s["reorder_sent"]:
        s["reorder_sent"].add(key)
        emit(s, "REORDER", sku, wh)
