"""Money helpers and data table loading. All money is integer cents."""
import os
import tomllib
from decimal import Decimal

_DATA = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data.toml")


def load_config(path=_DATA):
    with open(path, "rb") as f:
        return tomllib.load(f)


def round_decimal(value, mode):
    return int(Decimal(value).quantize(Decimal(1), rounding=mode))


def list_price(unit_cost, markup, mode):
    return round_decimal(Decimal(unit_cost) * (1 + Decimal(str(markup))), mode)


def sale_unit_price(price, qty, bulk_threshold, bulk_discount_pct, mode):
    if qty >= bulk_threshold:
        return round_decimal(Decimal(price) * (100 - Decimal(str(bulk_discount_pct))) / 100, mode)
    return price


def turnover(shiplog, held, current_day, current_units, start_day, end_day):
    """units shipped / average units held; None if the average is 0."""
    days = [d for d in range(start_day, end_day + 1) if d <= current_day]
    if not days:
        return None
    total = 0
    for d in days:
        total += current_units if d == current_day else held.get(d, 0)
    avg = total / len(days)
    if avg == 0:
        return None
    shipped = sum(q for d, q in shiplog if start_day <= d <= end_day)
    return shipped / avg
