"""Supplier reliability and orders (operate on the depot state dict)."""
from events import emit

START, LO, HI, SUSPEND_AT, REINSTATED = 3, 0, 5, 1, 2


def _err(code):
    from inventory import DepotError
    return DepotError(code)


def reliability(s, supplier):
    return s["rel"].get(supplier, START)


def place_order(s, supplier, sku, qty, due_day, wh=None):
    if supplier in s["rel"] and supplier in s["suspended"]:
        raise _err("SUPPLIER_SUSPENDED")
    s["rel"].setdefault(supplier, START)
    oid = s["next_order"]
    s["next_order"] += 1
    s["orders"][oid] = {"supplier": supplier, "sku": sku, "qty": qty,
                        "due_day": due_day, "wh": wh, "done": False}
    return oid


def record_delivery(s, supplier, late):
    r = s["rel"][supplier] + (-1 if late else 1)
    r = max(LO, min(HI, r))
    s["rel"][supplier] = r
    if r <= SUSPEND_AT and supplier not in s["suspended"]:
        s["suspended"].add(supplier)
        emit(s, "SUPPLIER_SUSPENDED", supplier)


def reinstate(s, supplier):
    if supplier not in s["rel"]:
        raise _err("UNKNOWN_SUPPLIER")
    s["rel"][supplier] = REINSTATED
    s["suspended"].discard(supplier)
