"""Seeded demand simulation."""
import random

import money


def simulate(days, seed):
    demand = money.load_config()["demand"]
    rng = random.Random(seed)
    out = []
    for _ in range(days):
        orders = []
        for sku, r in demand.items():
            q = rng.randint(r["min"], r["max"])
            if q > 0:
                orders.append((sku, q))
        out.append(orders)
    return out
