            if u == q:
                lots.pop(0)
            else:
                lots[0][1] -= u
        return taken

    def _flag(self, sku, wh, announce=False):
        events.update_reorder_flag(self._s, sku, wh, self._stock(sku, wh), announce)

    # ---- items ----
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        def f():
            if sku in self._s["items"]:
                raise DepotError("DUPLICATE_SKU")
            if not isinstance(unit_cost, int) or unit_cost <= 0:
                raise DepotError("INVALID_COST")
            if not isinstance(reorder_level, int) or reorder_level < 0:
                raise DepotError("INVALID_REORDER_LEVEL")
            sl = shelf_life_days
            if sl is not None and (not isinstance(sl, int) or sl < 0):
                raise DepotError("INVALID_SHELF_LIFE")
            if sl == 0:
                sl = 1  # see notes: 0 is treated as 1
            self._s["items"][sku] = {"unit_cost": unit_cost,
                                     "reorder_level": reorder_level,
                                     "shelf_life_days": sl}
        self._run(f)

    # ---- receiving ----
    def _receive(self, sku, qty, wh, cost=None):
        self._sku(sku)
        self._w(wh)
        _qty_ok(qty)
        s = self._s
        if s["cash"] < 0:
            raise DepotError("OVERDRAWN")
        if self._units(wh) + qty > self._cap[wh]:
            raise DepotError("CAPACITY")
        if cost is None:
            cost = s["items"][sku]["unit_cost"] * qty
        if s["cash"] - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        s["cash"] -= cost
        self._add_lot(sku, wh, qty, s["day"])
        self._flag(sku, wh)
        events.sync_overdraw(s)

    def receive(self, sku, qty, wh):
        self._run(lambda: self._receive(sku, qty, wh))

    def receive_bulk(self, receipts):
        def f():
            for sku, qty, wh in receipts:
                self._receive(sku, qty, wh)
        self._run(f)

    # ---- shipping ----
    def ship(self, sku, qty, wh, price):
        def f():
            self._sku(sku)
            self._w(wh)
            _qty_ok(qty)
            if not isinstance(price, int) or price < 0:
                raise DepotError("INVALID_PRICE")
            if self._stock(sku, wh) < qty:
                raise DepotError("INSUFFICIENT_STOCK")
            c = self._cfg
            unit = money.sale_unit_price(price, qty, c["bulk_threshold"],
                                         c["bulk_discount_pct"], self._mode)
            s = self._s
            s["cash"] += unit * qty
            self._take(sku, wh, qty)
            s["shipped"][sku] = s["shipped"].get(sku, 0) + qty
            s["shiplog"].append([s["day"], qty])
            self._flag(sku, wh, announce=True)
            events.sync_overdraw(s)
        self._run(f)

    def list_price(self, sku):
        self._sku(sku)
        return money.list_price(self._s["items"][sku]["unit_cost"],
                                self._cfg["markup"], self._mode)

    # ---- transfer ----
    def transfer(self, sku, qty, from_wh, to_wh):
        def f():
            self._sku(sku)
            self._w(from_wh)
            self._w(to_wh)
            _qty_ok(qty)
            if from_wh == to_wh:
                raise DepotError("SAME_WAREHOUSE")
            if self._stock(sku, from_wh) < qty:
                raise DepotError("INSUFFICIENT_STOCK")
            if self._units(to_wh) + qty > self._cap[to_wh]:
                raise DepotError("CAPACITY")
            s = self._s
            for d, q in self._take(sku, from_wh, qty):
                self._add_lot(sku, to_wh, q, d)
            s["cash"] -= self._cfg["transfer_credit_cents_per_unit"] * qty
            self._flag(sku, from_wh, announce=True)
            self._flag(sku, to_wh)
            events.sync_overdraw(s)
        self._run(f)

    # ---- returns ----
    def return_goods(self, sku, qty, wh, price):
        def f():
            self._sku(sku)
            self._w(wh)
            _qty_ok(qty)
            if not isinstance(price, int) or price < 0:
                raise DepotError("INVALID_PRICE")
            s = self._s
            if s["shipped"].get(sku, 0) - s["returned"].get(sku, 0) < qty:
                raise DepotError("RETURN_EXCEEDS")
            perishable = s["items"][sku]["shelf_life_days"] is not None
            restock = True
            if perishable:
                if self._ret_policy not in ("restock", "discard"):
                    raise DepotError("RETURN_POLICY_UNSET")
                restock = self._ret_policy == "restock"
            if restock:
                if self._units(wh) + qty > self._cap[wh]:
                    raise DepotError("CAPACITY")
                self._add_lot(sku, wh, qty, s["day"])
            s["cash"] -= price * qty
            s["returned"][sku] = s["returned"].get(sku, 0) + qty
            self._flag(sku, wh)
            events.sync_overdraw(s)
        self._run(f)

    # ---- time ----
    def advance_day(self):
        def f():
            s = self._s
            s["day"] += 1
            s["cash"] -= self._cfg["storage_cents_per_unit_day"] * self._total_units()
            for (sku, wh) in sorted(s["lots"]):
                sl = s["items"][sku]["shelf_life_days"]
                if sl is None:
                    continue
                lots = s["lots"][(sku, wh)]
                keep = [l for l in lots if s["day"] - l[0] <= sl]
                gone = sum(q for d, q in lots if s["day"] - d > sl)
                if gone:
                    s["lots"][(sku, wh)] = keep
                    emit(s, "EXPIRY", sku, wh, gone)
                    self._flag(sku, wh)
            events.sync_overdraw(s)
            s["held"][s["day"]] = self._total_units()
        self._run(f, blocks_undo=True)

    # ---- suppliers ----
    def place_order(self, supplier, sku, qty, due_day, wh=None):
        def f():
            self._sku(sku)
            _qty_ok(qty)
            if wh is not None:
                self._w(wh)
            return suppliers.place_order(self._s, supplier, sku, qty, due_day, wh)
        return self._run(f)

    def deliver(self, order_id, day):
        def f():
            s = self._s
            o = s["orders"].get(order_id)
            if o is None:
                raise DepotError("UNKNOWN_ORDER")
            if o["done"]:
                raise DepotError("ORDER_DELIVERED")
            late = day > o["due_day"]
            if o["wh"] is not None:
                cost = s["items"][o["sku"]]["unit_cost"] * o["qty"]
                if late:
                    if self._late_pct is None:
                        raise DepotError("LATE_PENALTY_UNSET")
                    cost = money.round_decimal(
                        money.Decimal(cost) * (100 - money.Decimal(str(self._late_pct))) / 100,
                        self._mode)
                self._receive(o["sku"], o["qty"], o["wh"], cost)
            o["done"] = True
            suppliers.record_delivery(s, o["supplier"], late)
        self._run(f)

    def reinstate(self, supplier):
        self._run(lambda: suppliers.reinstate(self._s, supplier))

    def reliability(self, supplier):
        return suppliers.reliability(self._s, supplier)

    # ---- audit / queries ----
    def audit(self, counts):
        def f():
            if not counts:
                raise DepotError("EMPTY_AUDIT")
            for sku, wh in counts:
                self._sku(sku)
                self._w(wh)
            for (sku, wh) in sorted(counts):
                led = self._stock(sku, wh)
                if led != counts[(sku, wh)]:
                    emit(self._s, "AUDIT_MISMATCH", sku, wh, led, counts[(sku, wh)])
        self._run(f)

    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is not None:
            self._w(wh)
            return self._stock(sku, wh)
        return sum(self._stock(sku, w) for w in self._wh)

    def report(self):
        rows = []
        for sku in sorted(self._s["items"]):
            for wh in sorted(self._wh):
                u = self._stock(sku, wh)
                if u:
                    rows.append((sku, wh, u, u * self._s["items"][sku]["unit_cost"]))
        return rows

    def turnover(self, start_day, end_day):
        if end_day < start_day:
            raise DepotError("BAD_RANGE")
        s = self._s
        return money.turnover(s["shiplog"], s["held"], s["day"],
                              self._total_units(), start_day, end_day)

    def notifications(self):
        return list(self._s["notes"])

    @property
    def cash(self):
        return self._s["cash"]

    @property
    def day(self):
        return self._s["day"]

    # ---- undo ----
    def undo(self):
        if self._undo is _BLOCKED:
            raise DepotError("UNDO_BLOCKED")
        if self._undo is None:
            raise DepotError("NOTHING_TO_UNDO")
        self._s = self._undo
        self._undo = None

    # ---- persistence ----
    def save(self):
        s = self._s
        data = {
            "version": 1,
            "day": s["day"], "cash": s["cash"], "items": s["items"],
            "lots": [[k[0], k[1], v] for k, v in s["lots"].items()],
            "reorder_sent": sorted(list(k) for k in s["reorder_sent"]),
            "overdrawn": s["overdrawn"],
            "notes": [list(n) for n in s["notes"]],
            "rel": s["rel"], "suspended": sorted(s["suspended"]),
            "orders": [[k, v] for k, v in s["orders"].items()],
            "next_order": s["next_order"], "shipped": s["shipped"],
            "returned": s["returned"], "shiplog": s["shiplog"],
            "held": [[k, v] for k, v in s["held"].items()],
        }
        return json.dumps(data)

    def load(self, text):
        try:
            d = json.loads(text)
            if not isinstance(d, dict) or d.get("version") != 1:
                raise ValueError
            new = {
                "day": int(d["day"]), "cash": int(d["cash"]),
                "items": dict(d["items"]),
                "lots": {(a, b): [[int(x), int(y)] for x, y in v] for a, b, v in d["lots"]},
                "reorder_sent": {(a, b) for a, b in d["reorder_sent"]},
                "overdrawn": bool(d["overdrawn"]),
                "notes": [tuple(n) for n in d["notes"]],
                "rel": {k: int(v) for k, v in d["rel"].items()},
                "suspended": set(d["suspended"]),
                "orders": {int(k): dict(v) for k, v in d["orders"]},
                "next_order": int(d["next_order"]),
                "shipped": dict(d["shipped"]), "returned": dict(d["returned"]),
                "shiplog": [[int(a), int(b)] for a, b in d["shiplog"]],
                "held": {int(k): int(v) for k, v in d["held"]},
            }
            for (sku, wh) in new["lots"]:
                if sku not in new["items"] or wh not in self._cap:
                    raise ValueError
            for it in new["items"].values():
                it["unit_cost"], it["reorder_level"], it["shelf_life_days"]
        except Exception:
            raise DepotError("BAD_SAVE")
        snap = self._s
        self._s = new
        self._undo = snap
